**Тестирование компонента:**
```javascript
import { test, expect } from '@playwright/experimental-ct-vue'
import Button from './Button.vue'

test('render button', async ({ mount }) => {
  const component = await mount(Button, {
    props: {
      label: 'Click me'
    }
  })

